
  CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id TEXT UNIQUE NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, college TEXT NOT NULL, class TEXT NOT NULL, password TEXT NOT NULL, role TEXT DEFAULT 'student', avatar TEXT DEFAULT '🌿', bio TEXT DEFAULT '', agent_name TEXT DEFAULT '知行', agent_avatar TEXT DEFAULT '✦', model_type TEXT DEFAULT 'deepseek', api_key TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS courses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, teacher TEXT, color TEXT DEFAULT '#d97745');
  CREATE TABLE IF NOT EXISTS resources (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT, title TEXT NOT NULL, description TEXT DEFAULT '', type TEXT DEFAULT 'note', tags TEXT DEFAULT '', url TEXT DEFAULT '', file_path TEXT DEFAULT '', file_name TEXT DEFAULT '', file_size BIGINT DEFAULT 0, is_pinned BIGINT DEFAULT 0, uploader_id BIGINT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS resource_folders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL, name TEXT NOT NULL, description TEXT DEFAULT '', tags TEXT DEFAULT '', uploader_id BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS schedules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, course_name TEXT NOT NULL, weekday BIGINT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, location TEXT DEFAULT '', color TEXT DEFAULT '#d97745');
  CREATE TABLE IF NOT EXISTS study_plans (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, status TEXT DEFAULT 'draft', due_date TEXT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS knowledge_points (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL, name TEXT NOT NULL, description TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(course_id,name));
  CREATE TABLE IF NOT EXISTS user_knowledge_mastery (user_id BIGINT NOT NULL, knowledge_point_id BIGINT NOT NULL, mastery DOUBLE PRECISION DEFAULT 0.5, attempts BIGINT DEFAULT 0, correct_count DOUBLE PRECISION DEFAULT 0, last_assessed_at TEXT DEFAULT '', updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(user_id,knowledge_point_id));
  CREATE TABLE IF NOT EXISTS learning_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, event_type TEXT NOT NULL, source_type TEXT DEFAULT '', source_id BIGINT, payload_json TEXT DEFAULT '{}', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS learning_reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, summary TEXT NOT NULL, period_label TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS quizzes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, thread_id BIGINT, course_id BIGINT, topic TEXT NOT NULL, title TEXT NOT NULL, quiz_json TEXT NOT NULL, answers_json TEXT DEFAULT '{}', result_json TEXT DEFAULT '{}', score DOUBLE PRECISION, total_score DOUBLE PRECISION, status TEXT DEFAULT 'created', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), completed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS question_favorites (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, quiz_id BIGINT NOT NULL, question_id TEXT NOT NULL, question_json TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(user_id,quiz_id,question_id));
  CREATE TABLE IF NOT EXISTS agent_threads (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, title TEXT DEFAULT '新的学习对话', mode TEXT DEFAULT 'study', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, thread_id BIGINT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, agent_type TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, thread_id BIGINT NOT NULL, file_name TEXT NOT NULL, file_path TEXT NOT NULL, mime_type TEXT DEFAULT '', file_size BIGINT DEFAULT 0, extracted_text TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS conversation_reads (conversation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, last_read_message_id BIGINT DEFAULT 0, updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(conversation_id,user_id));
  CREATE TABLE IF NOT EXISTS agent_memories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, memory_key TEXT NOT NULL, content TEXT NOT NULL, updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(user_id, memory_key));
  CREATE TABLE IF NOT EXISTS friend_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, from_user_id BIGINT NOT NULL, to_user_id BIGINT NOT NULL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(from_user_id, to_user_id));
  CREATE TABLE IF NOT EXISTS friendships (user_id BIGINT NOT NULL, friend_id BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(user_id, friend_id));
  CREATE TABLE IF NOT EXISTS friend_notes (user_id BIGINT NOT NULL, friend_id BIGINT NOT NULL, remark TEXT NOT NULL DEFAULT '', updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(user_id, friend_id));
  CREATE TABLE IF NOT EXISTS conversations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, type TEXT DEFAULT 'group', owner_id BIGINT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS conversation_members (conversation_id BIGINT, user_id BIGINT, PRIMARY KEY(conversation_id, user_id));
  CREATE TABLE IF NOT EXISTS group_learning_consents (conversation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, share_mastery BIGINT DEFAULT 0, share_plan_summary BIGINT DEFAULT 0, updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(conversation_id,user_id));
  CREATE TABLE IF NOT EXISTS group_tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, title TEXT NOT NULL, description TEXT DEFAULT '', assignee_id BIGINT, status TEXT DEFAULT 'todo', due_date TEXT DEFAULT '', created_by BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS group_summaries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, content TEXT NOT NULL, agenda_json TEXT DEFAULT '[]', proposals_json TEXT DEFAULT '[]', created_by BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, thread_id BIGINT, intent TEXT NOT NULL, status TEXT DEFAULT 'running', request_summary TEXT DEFAULT '', final_summary TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), completed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS agent_run_steps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL, step_index BIGINT NOT NULL, agent_type TEXT NOT NULL, status TEXT DEFAULT 'pending', input_summary TEXT DEFAULT '', output_summary TEXT DEFAULT '', citations_json TEXT DEFAULT '[]', started_at TEXT DEFAULT '', completed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS agent_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_user_id BIGINT, target_user_id BIGINT, run_id BIGINT, event_type TEXT NOT NULL, scope_json TEXT DEFAULT '{}', payload_json TEXT DEFAULT '{}', status TEXT DEFAULT 'created', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_collaboration_policies (user_id BIGINT NOT NULL, course_id BIGINT NOT NULL DEFAULT 0, allow_matching BIGINT DEFAULT 0, auto_respond BIGINT DEFAULT 0, share_mastery BIGINT DEFAULT 0, share_resource_titles BIGINT DEFAULT 1, updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(user_id,course_id));
  CREATE TABLE IF NOT EXISTS agent_delegations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requester_id BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, course_id BIGINT NOT NULL, question TEXT NOT NULL, requester_summary TEXT DEFAULT '', scope_json TEXT DEFAULT '{}', status TEXT DEFAULT 'pending', peer_answer TEXT DEFAULT '', synthesis TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), expires_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS agent_platform_permissions (user_id BIGINT PRIMARY KEY, allow_group_post BIGINT DEFAULT 0, allow_friend_broadcast BIGINT DEFAULT 0, allow_group_task BIGINT DEFAULT 0, allow_peer_delegation BIGINT DEFAULT 0, allow_resource_manage BIGINT DEFAULT 0, allow_forum_publish BIGINT DEFAULT 0, updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_platform_action_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, thread_id BIGINT, action_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), executed_at TEXT DEFAULT '', expires_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS agent_projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, title TEXT NOT NULL, goal TEXT NOT NULL, summary TEXT DEFAULT '', status TEXT DEFAULT 'active', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), completed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS agent_project_steps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL, step_order BIGINT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, description TEXT DEFAULT '', status TEXT DEFAULT 'pending', action_type TEXT DEFAULT '', action_payload_json TEXT DEFAULT '{}', result_json TEXT DEFAULT '{}', action_request_id BIGINT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_forum_drafts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, project_id BIGINT, title TEXT NOT NULL, content TEXT NOT NULL, category TEXT DEFAULT '学习交流', poll_question TEXT DEFAULT '', poll_options_json TEXT DEFAULT '[]', status TEXT DEFAULT 'draft', published_post_id BIGINT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS group_agent_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, initiator_id BIGINT NOT NULL, billing_user_id BIGINT NOT NULL, topic TEXT NOT NULL, status TEXT DEFAULT 'queued', turn_count BIGINT DEFAULT 0, max_turns BIGINT DEFAULT 12, stop_reason TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), stopped_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS group_agent_session_participants (session_id BIGINT NOT NULL, owner_user_id BIGINT NOT NULL, turn_order BIGINT NOT NULL, PRIMARY KEY(session_id,owner_user_id));
  CREATE TABLE IF NOT EXISTS group_attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, message_id BIGINT, created_by_user_id BIGINT NOT NULL, file_name TEXT NOT NULL, file_path TEXT NOT NULL, mime_type TEXT DEFAULT '', file_size BIGINT DEFAULT 0, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_delegation_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, delegation_id BIGINT NOT NULL, role TEXT NOT NULL, sender_user_id BIGINT, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS group_agent_activity (conversation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, last_auto_at BIGINT DEFAULT 0, PRIMARY KEY(conversation_id,user_id));
  CREATE TABLE IF NOT EXISTS group_agent_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, initiator_id BIGINT NOT NULL, billing_user_id BIGINT NOT NULL, topic TEXT NOT NULL, mode TEXT DEFAULT 'debate', status TEXT DEFAULT 'queued', current_round BIGINT DEFAULT 0, max_rounds BIGINT DEFAULT 2, max_agents BIGINT DEFAULT 2, final_summary TEXT DEFAULT '', stop_reason TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), completed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS group_agent_run_participants (run_id BIGINT NOT NULL, owner_user_id BIGINT NOT NULL, role TEXT DEFAULT 'participant', status TEXT DEFAULT 'pending', PRIMARY KEY(run_id,owner_user_id));
  CREATE TABLE IF NOT EXISTS group_agent_turns (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL, round_no BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, recipient_agent_owner_id BIGINT, kind TEXT NOT NULL, content TEXT NOT NULL, structured_json TEXT DEFAULT '{}', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_memory_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, scope_type TEXT NOT NULL DEFAULT 'personal', scope_id BIGINT, course_id BIGINT, memory_type TEXT NOT NULL DEFAULT 'note', title TEXT NOT NULL, summary TEXT NOT NULL, content_json TEXT DEFAULT '{}', source_type TEXT DEFAULT '', source_id BIGINT, status TEXT DEFAULT 'indexed', importance BIGINT DEFAULT 1, confidence DOUBLE PRECISION DEFAULT 0.6, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(user_id,source_type,source_id));
  CREATE TABLE IF NOT EXISTS memory_sync_preferences (user_id BIGINT NOT NULL, conversation_id BIGINT NOT NULL, mode TEXT DEFAULT 'ask', updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(user_id,conversation_id));
  CREATE TABLE IF NOT EXISTS memory_sync_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, memory_id BIGINT NOT NULL, user_id BIGINT NOT NULL, conversation_id BIGINT NOT NULL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), decided_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, sender_type TEXT DEFAULT 'user', agent_owner_id BIGINT, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS agent_group_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, requested_by_id BIGINT NOT NULL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS group_agents (conversation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, auto_reply BIGINT DEFAULT 0, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(conversation_id, user_id));
  CREATE TABLE IF NOT EXISTS friend_agent_access (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requester_id BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS friend_agent_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requester_id BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS friend_agent_attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, requester_id BIGINT NOT NULL, agent_owner_id BIGINT NOT NULL, message_id BIGINT NOT NULL, file_name TEXT NOT NULL, file_path TEXT NOT NULL, mime_type TEXT DEFAULT '', file_size BIGINT DEFAULT 0, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS forum_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author_id BIGINT NOT NULL, category TEXT DEFAULT '学习交流', title TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS forum_comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, author_id BIGINT NOT NULL, parent_comment_id BIGINT, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS forum_polls (post_id BIGINT PRIMARY KEY, question TEXT NOT NULL, options_json TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS forum_votes (post_id BIGINT NOT NULL, user_id BIGINT NOT NULL, option_index BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(post_id,user_id));
  CREATE TABLE IF NOT EXISTS announcements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL, is_pinned BIGINT DEFAULT 0, author_id BIGINT, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS teacher_tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, title TEXT NOT NULL, description TEXT DEFAULT '', task_type TEXT DEFAULT 'practice', due_at TEXT DEFAULT '', published BIGINT DEFAULT 0, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS teacher_task_submissions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT NOT NULL, student_id BIGINT NOT NULL, content TEXT NOT NULL, score DOUBLE PRECISION, feedback TEXT DEFAULT '', status TEXT DEFAULT 'submitted', submitted_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), graded_at TEXT DEFAULT '', UNIQUE(task_id,student_id));
  CREATE TABLE IF NOT EXISTS teacher_course_announcements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL, author_id BIGINT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, is_pinned BIGINT DEFAULT 0, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS course_student_memberships (course_id BIGINT NOT NULL, student_id BIGINT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(course_id,student_id));
  CREATE TABLE IF NOT EXISTS teacher_notes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, student_id BIGINT NOT NULL, content TEXT NOT NULL, created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS course_teacher_assignments (course_id BIGINT NOT NULL, user_id BIGINT NOT NULL, role TEXT DEFAULT 'teacher', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), PRIMARY KEY(course_id,user_id));
  CREATE TABLE IF NOT EXISTS teacher_forum_actions (post_id BIGINT PRIMARY KEY, teacher_id BIGINT NOT NULL, reply TEXT DEFAULT '', is_pinned BIGINT DEFAULT 0, status TEXT DEFAULT 'open', updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS account_deletion_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, status TEXT DEFAULT 'pending', note TEXT DEFAULT '', requested_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), reviewed_by BIGINT, reviewed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT, action TEXT NOT NULL, target_user_id BIGINT, target_student_id TEXT DEFAULT '', detail TEXT DEFAULT '', created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  CREATE TABLE IF NOT EXISTS sms_verifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, phone TEXT NOT NULL, purpose TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at BIGINT NOT NULL, attempts BIGINT DEFAULT 0, sent_at BIGINT NOT NULL, consumed_at BIGINT DEFAULT 0);
  CREATE TABLE IF NOT EXISTS resource_documents (resource_id BIGINT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending', error_message TEXT DEFAULT '', chunk_count BIGINT DEFAULT 0, processed_at TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS resource_chunks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, resource_id BIGINT NOT NULL, chunk_index BIGINT NOT NULL, content TEXT NOT NULL, page_number BIGINT, UNIQUE(resource_id, chunk_index));

